package fr.proutlost.worldprep.biome.v2;
import java.util.*;
/** Pure region selection. Coordinates are canonicalized, so sampling order and tick budget cannot affect output. */
public final class BiomeRegionPlanner { public record Cell(int x,int z,TerrainSemantic terrain,MacroClimate climate,int regionId){} public record Assignment(int x,int z,String biomeId){}
 public List<Assignment> plan(Collection<Cell> cells,BiomeCandidatePool pool,long seed,int diversityBudget){if(diversityBudget<1)throw new IllegalArgumentException();var result=new ArrayList<Assignment>();for(var cell:cells.stream().sorted(Comparator.comparingInt(Cell::regionId).thenComparingInt(Cell::x).thenComparingInt(Cell::z)).toList()){var family=family(cell);var choices=pool.candidates(family);if(choices.isEmpty())throw new IllegalStateException("No eligible biome for "+family);int bounded=Math.min(diversityBudget,choices.size());int index=Math.floorMod(Objects.hash(seed,cell.regionId(),family),bounded);result.add(new Assignment(cell.x(),cell.z(),choices.get(index).registryId()));}return List.copyOf(result);}
 private static BiomeFamily family(Cell c){return switch(c.terrain()){case DEEP_WATER,SHALLOW_WATER->BiomeFamily.OCEAN;case COAST->BiomeFamily.BEACH;case WETLAND->BiomeFamily.SWAMP;case MOUNTAIN->BiomeFamily.MOUNTAIN;case HIGHLAND->c.climate()==MacroClimate.COLD?BiomeFamily.TAIGA:BiomeFamily.FOREST;case LOWLAND->BiomeFamily.PLAINS;};}}
